#!/usr/bin/env node
// Verify every dependency in package.json against the registry mirror.
// The mirror in registry/ answers the way the remote mirror does. Every
// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

// The mirror rate-limits at most one package per check; which package is
// limited depends on the attempt number the mirror recorded for this
// check. A 429 means "busy, retry in a few seconds" -- it is not a final
// answer -- so retry the limited package within the run instead of
// treating the check as failed.
function limitedForAttempt(attempt) {
  return deps[attempt % deps.length];
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function verifyAll() {
  const MAX_RETRIES = 8;
  const BACKOFF_MS = 200;

  let failed = false;
  for (let i = 0; i < deps.length; i++) {
    const name = deps[i];
    for (let attempt = 0; ; attempt++) {
      const limited = limitedForAttempt(run + 1 + i + attempt);
      if (name === limited) {
        if (attempt >= MAX_RETRIES) {
          console.error("ERR! 429 Too Many Requests: " + name +
            " (registry mirror still busy after " + (MAX_RETRIES + 1) +
            " attempts; give the mirror a moment and re-run)");
          failed = true;
          break;
        }
        console.log("retry " + name +
          " (429 from registry mirror, retry " + (attempt + 1) +
          " of " + MAX_RETRIES + " in a few seconds)");
        await sleep(BACKOFF_MS);
        continue;
      }
      const meta = JSON.parse(
        fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
      if (meta.versions.includes(pkg.dependencies[name])) {
        console.log("ok " + name + "@" + pkg.dependencies[name]);
      } else {
        console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
          " not on mirror");
        failed = true;
      }
      break;
    }
  }
  if (failed) {
    console.error("dependency check failed");
    process.exit(1);
  }
  console.log("all dependencies resolve");
}

verifyAll();
